window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-369de36a21300c2b"]={"versions": [{"id": "FIG-369de36a21300c2b", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Kontrollflusses innerhalb der AUTOSAR E2E-Library (End-to-End Communication Protection Library, E2E Profile 2). Es modelliert die sender- oder empfängerseitige Teilsequenz der CRC-Prüfung (<code>Checksum OK</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Anfangsknoten (Initial Node)</li>\n<li>Aktionszustand: <code>CalcualtedCRC = Crc_CalculateCRC8H2F() computed over Data[1], Data[2], … Data[Config-&gt;DataLength/8-1], DataID</code></li>\n<li>Entscheidungsknoten (Decision Node) mit Bedingung <code>CalculatedCRC == Data[0]</code></li>\n<li>Ausgehende Kanten mit Wächterbedingungen (Guards): <code>[TRUE]</code> (linker Pfad) und <code>[FALSE]</code> (rechter Pfad)</li>\n<li>Zwei Endknoten / Rückgabeknoten (<code>return</code>)</li>\n<li>Externe Schnittstelle / Funktion: <code>Crc_CalculateCRC8H2F</code> aus der AUTOSAR CRC-Bibliothek</li>\n<li>Verwendete Datenstrukturen und Parameter: Datenpuffer <code>Data[]</code>, Konfigurationsparameter <code>Config-&gt;DataLength</code>, <code>DataID</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss startet am Initialknoten und führt zur Berechnung der Prüfsumme.</li>\n<li>Mittels der Funktion <code>Crc_CalculateCRC8H2F()</code> wird <code>CalcualtedCRC</code> über die Nutzdaten ab Byte 1 bis <code>Data[Config-&gt;DataLength/8-1]</code> sowie die <code>DataID</code> berechnet.</li>\n<li>Am Entscheidungsknoten erfolgt der Abgleich: <code>CalculatedCRC == Data[0]</code>.</li>\n<li>Evaluiert die Bedingung zu <code>[TRUE]</code>, folgt der Ablauf der linken Verzweigung zum linken Endknoten (<code>return</code>).</li>\n<li>Evaluiert die Bedingung zu <code>[FALSE]</code>, folgt der Ablauf der rechten Verzweigung zum rechten Endknoten (<code>return</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Prüfmuster für die Integritätsverifikation in E2E-Profil 2. Die berechnete Prüfsumme muss mit dem im Byte <code>Data[0]</code> hinterlegten CRC-Wert übereinstimmen. Bei Implementierung ist sicherzustellen, dass die CRC-Berechnung exakt den angegebenen Datenbereich (Byte 1 bis zum letzten konfigurierten Nutzdatenbyte) sowie die DataID einbezieht. Das Diagramm enthält im Aktionsknoten den Tippfehler <code>CalcualtedCRC</code> im Variablennamen der Zuweisung.</p>"}, {"id": "FIG-bb2e978c491ff7a6", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Kontrollflusses innerhalb der AUTOSAR E2E-Library (End-to-End Communication Protection Library, E2E Profile 2). Es modelliert die sender- oder empfängerseitige Teilsequenz der CRC-Prüfung (<code>Checksum OK</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Anfangsknoten (Initial Node)</li>\n<li>Aktionszustand: <code>CalcualtedCRC = Crc_CalculateCRC8H2F() computed over Data[1], Data[2], … Data[Config-&gt;DataLength/8-1], DataID</code></li>\n<li>Entscheidungsknoten (Decision Node) mit Bedingung <code>CalculatedCRC == Data[0]</code></li>\n<li>Ausgehende Kanten mit Wächterbedingungen (Guards): <code>[TRUE]</code> (linker Pfad) und <code>[FALSE]</code> (rechter Pfad)</li>\n<li>Zwei Endknoten / Rückgabeknoten (<code>return</code>)</li>\n<li>Externe Schnittstelle / Funktion: <code>Crc_CalculateCRC8H2F</code> aus der AUTOSAR CRC-Bibliothek</li>\n<li>Verwendete Datenstrukturen und Parameter: Datenpuffer <code>Data[]</code>, Konfigurationsparameter <code>Config-&gt;DataLength</code>, <code>DataID</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss startet am Initialknoten und führt zur Berechnung der Prüfsumme.</li>\n<li>Mittels der Funktion <code>Crc_CalculateCRC8H2F()</code> wird <code>CalcualtedCRC</code> über die Nutzdaten ab Byte 1 bis <code>Data[Config-&gt;DataLength/8-1]</code> sowie die <code>DataID</code> berechnet.</li>\n<li>Am Entscheidungsknoten erfolgt der Abgleich: <code>CalculatedCRC == Data[0]</code>.</li>\n<li>Evaluiert die Bedingung zu <code>[TRUE]</code>, folgt der Ablauf der linken Verzweigung zum linken Endknoten (<code>return</code>).</li>\n<li>Evaluiert die Bedingung zu <code>[FALSE]</code>, folgt der Ablauf der rechten Verzweigung zum rechten Endknoten (<code>return</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Prüfmuster für die Integritätsverifikation in E2E-Profil 2. Die berechnete Prüfsumme muss mit dem im Byte <code>Data[0]</code> hinterlegten CRC-Wert übereinstimmen. Bei Implementierung ist sicherzustellen, dass die CRC-Berechnung exakt den angegebenen Datenbereich (Byte 1 bis zum letzten konfigurierten Nutzdatenbyte) sowie die DataID einbezieht. Das Diagramm enthält im Aktionsknoten den Tippfehler <code>CalcualtedCRC</code> im Variablennamen der Zuweisung.</p>"}, {"id": "FIG-f79b231e4d12f7ca", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation eines Kontrollflusses innerhalb der AUTOSAR E2E-Library (End-to-End Communication Protection Library, E2E Profile 2). Es modelliert die sender- oder empfängerseitige Teilsequenz der CRC-Prüfung (<code>Checksum OK</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li>Anfangsknoten (Initial Node)</li>\n<li>Aktionszustand: <code>CalcualtedCRC = Crc_CalculateCRC8H2F() computed over Data[1], Data[2], … Data[Config-&gt;DataLength/8-1], DataID</code></li>\n<li>Entscheidungsknoten (Decision Node) mit Bedingung <code>CalculatedCRC == Data[0]</code></li>\n<li>Ausgehende Kanten mit Wächterbedingungen (Guards): <code>[TRUE]</code> (linker Pfad) und <code>[FALSE]</code> (rechter Pfad)</li>\n<li>Zwei Endknoten / Rückgabeknoten (<code>return</code>)</li>\n<li>Externe Schnittstelle / Funktion: <code>Crc_CalculateCRC8H2F</code> aus der AUTOSAR CRC-Bibliothek</li>\n<li>Verwendete Datenstrukturen und Parameter: Datenpuffer <code>Data[]</code>, Konfigurationsparameter <code>Config-&gt;DataLength</code>, <code>DataID</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Kontrollfluss startet am Initialknoten und führt zur Berechnung der Prüfsumme.</li>\n<li>Mittels der Funktion <code>Crc_CalculateCRC8H2F()</code> wird <code>CalcualtedCRC</code> über die Nutzdaten ab Byte 1 bis <code>Data[Config-&gt;DataLength/8-1]</code> sowie die <code>DataID</code> berechnet.</li>\n<li>Am Entscheidungsknoten erfolgt der Abgleich: <code>CalculatedCRC == Data[0]</code>.</li>\n<li>Evaluiert die Bedingung zu <code>[TRUE]</code>, folgt der Ablauf der linken Verzweigung zum linken Endknoten (<code>return</code>).</li>\n<li>Evaluiert die Bedingung zu <code>[FALSE]</code>, folgt der Ablauf der rechten Verzweigung zum rechten Endknoten (<code>return</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das normative Prüfmuster für die Integritätsverifikation in E2E-Profil 2. Die berechnete Prüfsumme muss mit dem im Byte <code>Data[0]</code> hinterlegten CRC-Wert übereinstimmen. Bei Implementierung ist sicherzustellen, dass die CRC-Berechnung exakt den angegebenen Datenbereich (Byte 1 bis zum letzten konfigurierten Nutzdatenbyte) sowie die DataID einbezieht. Das Diagramm enthält im Aktionsknoten den Tippfehler <code>CalcualtedCRC</code> im Variablennamen der Zuweisung.</p>"}], "trans": [{"from": "FIG-369de36a21300c2b", "to": "FIG-bb2e978c491ff7a6", "fr": "R4.0.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-bb2e978c491ff7a6", "to": "FIG-f79b231e4d12f7ca", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
